:root { 
  --primary: #f84464;
  --bg: #0b0f1a;
  --card: #161d2f;
  --glass: rgba(255, 255, 255, 0.06);
  --text: #fff;
  --text-dim: #94a3b8;
  --success: #4caf50;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  font-family: Poppins;
  text-decoration: none;
}

body {
  background: var(--bg);
  color: var(--text);
  overflow-x: hidden;
}

.hidden {
  display: none !important;
}

/* ================= NAVBAR ================= */

nav {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 15px 8%;
  background: #0b0f1af0;
  border-bottom: 1px solid rgba(255,255,255,0.05);
  flex-wrap: wrap;
}

.logo {
  font-size: 26px;
  font-weight: 700;
  color: var(--primary);
  cursor: pointer;
}

.navb {
  display: flex;
  align-items: center;
  flex-wrap: wrap;
}

.navb span {
  margin-left: 25px;
  cursor: pointer;
  color: var(--text-dim);
  transition: 0.3s;
}

.navb span:hover {
  color: var(--primary);
}

/* Search */

.search-form {
  flex: 1;
  display: flex;
  justify-content: center;
}

.search-input {
  width: 350px;
  max-width: 100%;
  padding: 10px 18px;
  border-radius: 30px;
  border: 1px solid rgba(255,255,255,0.1);
  background: #1a2236;
  color: #ffffff;

  font-size: 14px;
  outline: none;
  transition: all 0.3s ease;
}

.search-input::placeholder {
  color: #94a3b8;
}

.search-input:focus {
  border: 1px solid var(--primary);
  box-shadow: 0 0 10px rgba(248, 68, 100, 0.5);
  background: #202a45;
}

/* ================= PAGE ================= */

.page {
  padding: 60px 8%;
  min-height: 90vh;
}

/* ================= MOVIE GRID ================= */

.movie-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 30px;
}

.movie-card {
  background: var(--card);
  border-radius: 15px;
  overflow: hidden;
  cursor: pointer;
  transition: transform .3s ease, box-shadow .3s ease;
  display: flex;
  flex-direction: column;
  height: 100%;
}

.movie-card:hover {
  transform: translateY(-6px);
  box-shadow: 0 10px 25px rgba(0,0,0,0.4);
}

.movie-card img {
  width: 100%;
  height: clamp(220px, 30vw, 320px);
  object-fit: cover;
}

.movie-card div {
  padding: 15px;
  flex: 1;
}

/* ================= AUTH ================= */

.auth-overlay {
  position: fixed;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background: rgba(0, 0, 0, 0.8);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 2000;
  padding: 20px;
}

.auth-page {
  min-height: 90vh;
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 20px;
}

.auth-card {
  background: #161d2f;
  padding: 40px;
  width: 100%;
  max-width: 400px;
  border-radius: 12px;
  text-align: center;
}

input {
  width: 100%;
  padding: 12px;
  margin-bottom: 15px;
  border-radius: 10px;
  border: 1px solid #334;
  background: #1a2236;
  color: #fff;
}

/* ================= BUTTON ================= */

.btn {
  padding: 12px 24px;
  border: none;
  border-radius: 10px;
  cursor: pointer;
  font-weight: 600;
  transition: 0.3s;
}

.btn-primary {
  background: var(--primary);
  color: #fff;
  width: 100%;
}

.btn:active {
  transform: scale(0.98);
}

.glass-panel {
  background: var(--glass);
  border: 1px solid rgba(255, 255, 255, 0.1)
}


/* ================= SEATS ================= */

.row {
  display: flex;
  justify-content: center;
  gap: 8px;
  flex-wrap: wrap;
}

.seat {
  width: 30px;
  height: 30px;
  background: #2e3748;
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 10px;
  cursor: pointer;
}

.seat.selected {
  background: var(--primary);
}

.screen {
  background: #00d2ff;
  padding: 8px;
  border-radius: 20px;
  margin: 30px 0;
  box-shadow: 0 10px 25px rgba(0, 210, 255, 0.6);
  color: #000;
  font-weight: bold;
  font-size: 12px;

}

/* ================= ADMIN TABLE ================= */

table {
  width: 100%;
  border-collapse: collapse;
  margin-top: 20px;
  background: var(--card);
  border-radius: 10px;
  overflow-x: auto;
  overflow: hidden;
}

th, td {
  padding: 15px;
  text-align: left;
  border-bottom: 1px solid #2e3748;
  white-space: nowrap;
}

th {
  background: #1a2236;
  color: var(--primary);
}

/* ================= TICKET ================= */

.ticket {
  background: #fff;
  color: #000;
  border-radius: 15px;
  display: flex;
  flex-wrap: wrap;
  max-width: 600px;
  margin: 20px auto;
  overflow: hidden;
}

.ticket-left {

  padding: 25px;
  flex: 2;
  border-right: 2px dashed #ccc;
}

.ticket-right {
  flex: 1;
  background: #f1f1f1;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
}

/* ================= ICON ================= */

i {
  font-size: clamp(28px, 5vw, 50px);
  display: block;
  margin: 0px 0px 5px auto;
  text-align: center;
  transition: 0.3s ease;
}

/* ================= RESPONSIVE ================= */

@media (max-width: 992px) {

  nav {
    padding: 15px 5%;
  }

  .search-input {
    width: 250px;
  }

  .page {
    padding: 50px 5%;
  }

  .movie-grid {
    gap: 25px;
  }

  .ticket {
    flex-direction: column;
  }

  .ticket-left {
    border-right: none;
    border-bottom: 2px dashed #ccc;
  }
}

@media (max-width: 576px) {

  nav {
    flex-direction: column;
    gap: 15px;
  }

  .navb span {
    margin-left: 15px;
    font-size: 14px;
  }

  .search-input {
    width: 100%;
  }

  .movie-grid {
    grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
    gap: 20px;
  }

  .seat {
    width: 24px;
    height: 24px;
    font-size: 8px;
  }

  .auth-card {
    padding: 25px;
  }

  th, td {
    padding: 10px;
    font-size: 12px;
  }

  .screen {
    font-size: 10px;
  }
}

const MovieCard = ({ movie }) => {
  const navigate = useNavigate();
  const image = `https://image.tmdb.org/t/p/w500${movie.poster_path}`;

