const Ticket = ({ booking }) => {
  const [timeLeft, setTimeLeft] = useState("");

  useEffect(() => {

    const calculateTimeLeft = () => {

      const createdTime = new Date(booking.createdAt).getTime();

      const expiryTime = createdTime + 5 * 60 * 60 * 1000;
      const now = new Date().getTime();

      const difference = expiryTime - now;

      if (difference <= 0) {
        setTimeLeft("EXPIRED");
        return;
      }


      const hours = Math.floor((difference / (1000 * 60 * 60)) % 24);
      const minutes = Math.floor((difference / 1000 / 60) % 60);
      const seconds = Math.floor((difference / 1000) % 60);

      setTimeLeft(`${hours}h ${minutes}m ${seconds}s`);
    };


    const timer = setInterval(calculateTimeLeft, 1000);
    calculateTimeLeft();

    return () => clearInterval(timer);
  }, [booking.createdAt]);

  return (
    <div className="ticket" style={{ position: 'relative' }}>
      <div className="ticket-left">
        <small style={{ color: timeLeft === "EXPIRED" ? "#64748b" : "#f84464", fontWeight: "700" }}>
          {timeLeft === "EXPIRED" ? "INVALID / EXPIRED" : "CONFIRMED"}
        </small>
        <h3>{booking.movie}</h3>
        <p><strong>Showtime:</strong> {booking.showtime}</p>
        <p><strong>Seats:</strong> {booking.seats.join(", ")}</p>
        <p><strong>Amount:</strong> ₹{booking.total}</p>


        <div style={{ 
          marginTop: "10px", 
          padding: "5px 10px", 
          background: "rgba(255,255,255,0.05)", 
          borderRadius: "5px",
          display: "inline-block",
          fontSize: "12px"
        }}>
          <span style={{ color: "var(--text-dim)" }}>Expires in: </span>
          <span style={{ color: timeLeft === "EXPIRED" ? "red" : "#ffd700", fontWeight: "bold" }}>
            {timeLeft}
          </span>
        </div>
      </div>
      <div className="ticket-right">#{booking.id}</div>
    </div>
  );
};

export default Ticket;

const Admin = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(
    localStorage.getItem("adminAuth") === "true"
  );
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [bookings, setBookings] = useState([]);

const handleLogin = async (e) => {
  e.preventDefault();

  try {
    const res = await axios.post(
      "https://showtime-project-server.onrender.com/api/auth/login",
      {
        email: username,
        password: password,
      }
    );

    if (res.data.user.role === "admin") {
      localStorage.setItem("token", res.data.token);
      localStorage.setItem("user", JSON.stringify(res.data.user));
      localStorage.setItem("adminAuth", "true");
      setIsAuthenticated(true);
    } else {
      alert("Access Denied: You are not an Admin");
    }
  } catch (err) {
    alert(err.response?.data || "Invalid Admin Credentials");
  }
};

  const handleLogout = () => {
    localStorage.removeItem("adminAuth");
    localStorage.removeItem("token");
    localStorage.removeItem("user");
    setIsAuthenticated(false);
  };

  useEffect(() => {
    if (isAuthenticated) {
      axios
        .get(
          "https://showtime-project-server.onrender.com/api/bookings/all",
          {
            headers: {
              Authorization: `Bearer ${localStorage.getItem("token")}`,
            },
          }
        )
        .then((res) => setBookings(res.data))
        .catch((err) => console.log(err));
    }
  }, [isAuthenticated]);

  if (!isAuthenticated) {
    return (
      <div className="auth-page">
        <div className="auth-card">
          <h2>Admin Login</h2>
          <form onSubmit={handleLogin}>
            <input
              type="text"
              placeholder="Admin Email"
              value={username}
              onChange={(e) => setUsername(e.target.value)}
              required
            />
            <input
              type="password"
              placeholder="Password"
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              required
            />
            <button className="btn btn-primary" type="submit">
              Login
            </button>
          </form>
        </div>
      </div>
    );
  }

  const revenue = bookings.reduce((sum, b) => sum + b.total, 0);

  return (
    <div className="page">
      <h2>Admin Dashboard</h2>

      <button
        className="btn"
        onClick={handleLogout}
        style={{ float: "right", marginBottom: "20px" }}
      >
        Logout
      </button>

      <h3>Total Bookings: {bookings.length}</h3>
      <h3>Total Revenue: ₹{revenue}</h3>

      <table>
        <thead>
